const RETRYABLE = new Set([408, 429, 500, 502, 503, 504]);

function retryAfterMs(header, now) {
  if (typeof header !== 'string') return null;
  const text = header.trim();
  if (/^\d+$/.test(text)) {
    const delay = Number(text) * 1000;
    return Number.isFinite(delay) ? delay : null;
  }
  if (!/^[A-Z][a-z]{2}, \d{2} [A-Z][a-z]{2} \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(text)) {
    return null;
  }
  const time = Date.parse(text);
  return Number.isFinite(time) ? Math.max(0, time - now) : null;
}

return $input.all().map(({json}) => {
  const {status, attempt, safeToReplay, retryAfter} = json;
  const stop = reason => ({json: {status, action: 'stop', reason}});
  if (!Number.isInteger(status) || status < 100 || status > 599 ||
      !Number.isInteger(attempt) || attempt < 1) return stop('invalid_input');
  if (!RETRYABLE.has(status)) return stop('status_outside_retry_policy');
  if (safeToReplay !== true) return stop('replay_not_confirmed_safe');
  if (attempt >= 3) return stop('attempt_limit');
  const delay = Math.max(2 ** attempt * 1000, retryAfterMs(retryAfter, Date.now()) ?? 0);
  if (delay > 120000) return stop('wait_exceeds_local_budget');
  return {json: {status, action: 'retry_candidate', delayMs: delay}};
});
